      "confidence": 0.9
    },
    {
      "category": "extra_component",
      "components": ["U2", "U4"],
      "pins": ["U2.1", "U2.2", "U2.3", "U2.5", "U2.6", "U2.7", "U4.1", "U4.2", "U4.3", "U4.5", "U4.6", "U4.7"],
